const $=id=>document.getElementById(id);
function activate(mode){const ref=mode==='breakdown';document.body.dataset.mode=mode;$('editor-pane').hidden=ref;$('breakdown').hidden=!ref;document.querySelectorAll('[data-pane]').forEach(btn=>{const active=btn.dataset.pane===mode;btn.classList.toggle('active',active);btn.setAttribute('aria-selected',String(active));btn.tabIndex=active?0:-1});$('page-label').textContent=ref?'参考视频拉片':'剪辑创作';$('page-eyebrow').textContent=ref?'LEARN THE RHYTHM. MAKE IT YOURS.':'CREATE SOMETHING WORTH WATCHING';$('page-title').replaceChildren(document.createTextNode(ref?'好视频，值得拆开看':'把灵感，剪成作品'));const dot=document.createElement('span');dot.textContent='。';$('page-title').append(dot);$('page-description').textContent=ref?'看清镜头安排、读懂文案逻辑，把参考变成自己的创作方法。':'整理素材，编排镜头，让你的下一个故事从这里开始。';$('preview').pause();$('ref-player').pause();document.dispatchEvent(new Event('workspace-navigation'))}
document.querySelectorAll('[data-pane]').forEach(btn=>{btn.onclick=()=>{history.replaceState(null,'',`#${btn.dataset.pane}`);activate(btn.dataset.pane)};btn.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const mode=e.key==='Home'?'edit':e.key==='End'?'breakdown':btn.dataset.pane==='edit'?'breakdown':'edit';activate(mode);$(`tab-${mode}`).focus()}}});
$('open-ai-settings').onclick=()=>{history.replaceState(null,'','#edit');activate('edit');document.querySelector('.creation-settings').open=true;$('ai-settings').open=true;$('ai-settings').scrollIntoView({behavior:'smooth',block:'center'});$('api').focus()};window.addEventListener('hashchange',()=>activate(location.hash==='#breakdown'?'breakdown':'edit'));activate(location.hash==='#breakdown'?'breakdown':'edit');

function jumpTo(mode,id){history.replaceState(null,'',`#${mode}`);activate(mode);const el=$(id);el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});if(el.hasAttribute('tabindex'))el.focus({preventScroll:true})}
$('nav-assets').onclick=()=>jumpTo('edit',$('asset-pool').hidden?'video-dropzone':'asset-pool');
$('nav-results').onclick=()=>jumpTo('breakdown','ref-results');
$('nav-teaching').onclick=()=>jumpTo('breakdown','reference-teaching');
$('ref-view-results').onclick=()=>jumpTo('breakdown','ref-results');
$('ref-results-teaching').onclick=()=>jumpTo('breakdown','reference-teaching');
